<?php require 'header.php'; $stats=[];foreach(['Total products'=>'SELECT COUNT(*) FROM products','Samsung products'=>'SELECT COUNT(*) FROM products WHERE brand="Samsung"','iPhone products'=>'SELECT COUNT(*) FROM products WHERE brand="Apple"','In stock'=>'SELECT COUNT(*) FROM products WHERE stock>0','Out of stock'=>'SELECT COUNT(*) FROM products WHERE stock=0'] as $label=>$sql)$stats[$label]=db()->query($sql)->fetchColumn();$latest=db()->query('SELECT name,brand,price,stock FROM products ORDER BY created_at DESC LIMIT 6')->fetchAll();?><div class="admin-title"><p>OVERVIEW</p><h2>Store dashboard</h2></div><div class="stats"><?php foreach($stats as $label=>$value): ?><div><span><?=e($label)?></span><strong><?=$value?></strong></div><?php endforeach ?></div><section class="admin-panel"><h2>Recently added products</h2><?php if($latest): ?><table><thead><tr><th>Product</th><th>Brand</th><th>Price</th><th>Stock</th></tr></thead><tbody><?php foreach($latest as $p): ?><tr><td><?=e($p['name'])?></td><td><?=e($p['brand'])?></td><td><?=money($p['price'])?></td><td><?=$p['stock']?></td></tr><?php endforeach ?></tbody></table><?php else:?><p>No products yet. <a href="add-product.php">Add the first phone.</a></p><?php endif ?></section><?php require 'footer.php'; ?>
